const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    if (input.length < 4) return;

    let N = input[0];
    const costs = [input[1], input[2], input[3]].sort((a, b) => a - b);

    let count = 0;
    for (const cost of costs) {
        if (N >= cost) {
            N -= cost;
            count++;
        } else {
            break;
        }
    }

    console.log(count);
}

solve();
